import javax.crypto.*;import javax.crypto.spec.*;import java.util.*;import java.security.*;import java.nio.charset.*;
public class AES{public static void main(String[]x)throws Exception{String msg="www.annauniv.edu",password="annaUniversity";byte[]k=Arrays.copyOf(MessageDigest.getInstance("SHA-1").digest(password.getBytes(StandardCharsets.UTF_8)),16);Cipher c=Cipher.getInstance("AES/ECB/PKCS5Padding");SecretKeySpec key=new SecretKeySpec(k,"AES");c.init(Cipher.ENCRYPT_MODE,key);String e=Base64.getEncoder().encodeToString(c.doFinal(msg.getBytes(StandardCharsets.UTF_8)));c.init(Cipher.DECRYPT_MODE,key);System.out.println("Original URL: "+msg);System.out.println("Encrypted URL: "+e);System.out.println("Decrypted URL: "+new String(c.doFinal(Base64.getDecoder().decode(e)),StandardCharsets.UTF_8));}}
